function aggregate({ sessions, questions, reviews }, range) {
  const selectedSessions = sessions.filter(i => within(i, range.start, range.end));
  const selectedQuestions = questions.filter(i => within(i, range.start, range.end));
  const selectedReviews = reviews.filter(i => within(i, range.start, range.end) && ['Concluído', 'completed', 'done'].includes(i.status));
  const resolved = sum(selectedQuestions, 'resolved');
  return {
    minutes: Math.round(sum(selectedSessions, 'durationSeconds') / 60),
    questions: resolved,
    accuracy: resolved ? Math.round(sum(selectedQuestions, 'correct') / resolved * 100) : null,
    reviews: selectedReviews.length
  };
}
